#!/usr/bin/env python3
"""Show interpreter and installed packages."""
import sys
import pkg_resources

print(f"sys.executable: {sys.executable}")
print(f"sys.version: {sys.version}")
print("--- installed packages ---")
try:
    for dist in sorted(pkg_resources.working_set, key=lambda d: d.key):
        print(f"{dist.key}=={dist.version}")
except Exception as exc:
    print(f"pkg_resources error: {exc}")

#!/usr/bin/env python3
"""Inspect interpreter, sys.path, and site-packages contents."""
import os
import site
import sys

print(f"sys.executable: {sys.executable}")
print(f"sys.prefix: {sys.prefix}")
print("sys.path:")
for p in sys.path:
    print(f"  {p}")

for sp in site.getsitepackages():
    print(f"site-packages: {sp}")
    try:
        entries = sorted(os.listdir(sp))
        print(f"  {len(entries)} entries")
        for e in entries:
            print(f"    {e}")
    except OSError as exc:
        print(f"  cannot list: {exc}")

#!/usr/bin/env python3
"""List contents of the pdf skill directory and check for vendored libs."""
import os

root = ".codex/skills/pdf"
print(f"Exists: {os.path.isdir(root)}")
for dirpath, dirnames, filenames in os.walk(root):
    depth = dirpath[len(root):].count(os.sep)
    if depth > 3:
        continue
    indent = "  " * depth
    print(f"{indent}{dirpath}/")
    for f in sorted(filenames):
        print(f"{indent}  {f}")

